    for name in ['pyproject.toml','uv.lock']:(root/name).write_text('original')
    history=root/'migrations';history.mkdir();(history/'one.py').write_text('# revision')
    custom=root/'custom';custom.mkdir();(custom/'helper.py').write_text('VALUE=42')
    (bundle/'payload').write_text('runtime');(bundle/'payload').chmod(0o755)
    from verify_bundle import migration_inputs
    inputs=['pyproject.toml','uv.lock',*migration_inputs(root)]
    record={'schema_version':1,'python_version':'3.15.0','uv_version':'0.13.1','inputs':{n:digest(root/n) for n in inputs},'owner_sources':{'custom/helper.py':digest(custom/'helper.py')},'files':inventory(bundle)}
    (bundle/'provenance.json').write_text(json.dumps(record));return bundle

