@pytest.mark.parametrize('directory',['.','python','python/lib'])
def test_directory_mode_drift_invalidates_bundle(tmp_path,directory):
    bundle=binding_fixture(tmp_path);(bundle/'python/lib').mkdir(parents=True)
    record=json.loads((bundle/'provenance.json').read_text());record['files']=inventory(bundle)
    (bundle/'provenance.json').write_text(json.dumps(record));verify(tmp_path,bundle)
    target=bundle/directory;before=target.stat().st_mode;target.chmod(0o700 if before&0o777!=0o700 else 0o755)
    with pytest.raises(RuntimeError,match='production_bundle_invalid'):verify(tmp_path,bundle)

