def test_interpreter_copy_excludes_inherited_global_packages(tmp_path):
    from package_production import copy_interpreter
    source=tmp_path/'selected';(source/'lib/python3.15/site-packages/contamination').mkdir(parents=True)
    (source/'lib/python3.15/site-packages/contamination/__init__.py').write_text('INHERITED=True')
    (source/'lib/python3.15/os.py').write_text('# stdlib')
    copy_interpreter(source,tmp_path/'copied')
    assert (tmp_path/'copied/lib/python3.15/os.py').is_file()
    assert not (tmp_path/'copied/lib/python3.15/site-packages').exists()

