@pytest.mark.parametrize('filename',['new.py','__init__.py','nested/new.py'])
def test_selected_directory_addition_cli_refuses(tmp_path,filename):
    import subprocess
    import sys
    bundle=binding_fixture(tmp_path)
    record=json.loads((bundle/'provenance.json').read_text());record['owner_roots']={'custom':'directory'}
    (bundle/'provenance.json').write_text(json.dumps(record))
    added=tmp_path/'custom'/filename;added.parent.mkdir(parents=True,exist_ok=True);added.write_text('VALUE=99')
    command=[sys.executable,str(Path(__file__).resolve().parents[1]/'verify_bundle.py'),'--root',str(tmp_path),'--bundle',str(bundle)]
    result=subprocess.run(command,capture_output=True,text=True)
    assert result.returncode!=0
    assert result.stderr.strip()=='production_bundle_invalid'
    assert (bundle/'provenance.json').is_file() and added.is_file()
